import {HOMES,SLOTS,STATIONS,clamp,occupied} from './simulation.js';
import {recovery} from './guidance.js';
export function destinations(id,s,studio){const target=(key,position)=>({key,position:[...position],radius:.26}),glass=studio.mouth('glass');if(id==='portafilter')return[target('grinder',SLOTS.grinder),target('group',SLOTS.group)];if(id==='tamper')return s.grounds>0&&s.lock<.1?[target('tamp',s.objects.portafilter.position)]:[];if(id==='iceScoop')return[target('iceScoop',glass),target('iceBucket',[3.05,.65,1.74])];if(id.startsWith('ice'))return[target('ice',glass)];if(id==='glass')return occupied(s.vessels.glass)>1?[target('serve',STATIONS.coaster)]:[];if(id==='spoon')return s.spoonLoaded?[target('sugar',glass)]:[target('scoop',[STATIONS.sugar[0],.28,STATIONS.sugar[2]]),target('stir',glass)];const list=id==='cup'?[target('brew',SLOTS.brew)]:[];if(s.canPour(id))list.push(target('pour',glass));return list;}
export function bindInteractions(studio,s,{reset,toggleSound,onChange=()=>{},onError=()=>{}}){
 const canvas=studio.canvas,pointers=new Set();let gesture=null;
 const save=o=>({position:[...o.position],slot:o.slot??null,tilt:o.tilt??0,lock:s.lock});
 function restore(id,a){s.put(id,a.position,a.slot);if(id==='portafilter')s.lock=a.lock;}
 function settle(g){const p=studio.onCounter?.(g.x,g.y)??s.object(g.id).position;s.placeOnCounter(g.id,p);}
 function nearest(id,x,y){let best=null,dist=Infinity;const object=s.object(id),anchor=object?studio.project(object.position):{x,y};for(const d of destinations(id,s,studio)){const p=studio.project(d.position),distance=Math.min(Math.hypot(x-p.x,y-p.y),Math.hypot(anchor.x-p.x,anchor.y-p.y));if(distance<(d.key==='pour'||d.key==='iceScoop'?100:72)&&distance<dist){dist=distance;best=d;}}return best;}
 function finish(cancel=false){if(!gesture)return;const g=gesture;gesture=null;s.stop({keepBrew:!cancel,keepAutomatic:!cancel});studio.controls.enabled=true;studio.setTargets([]);canvas.style.cursor='grab';
  if(g.saved){if(cancel){restore(g.id,g.saved);delete s.objects[g.id]?.pourHome;}else if(g.mode==='tamp'){s.tamp(1);s.returnHome('tamper');}else if(g.mode==='pour'){if(!s.autoPour(g.id))s.returnHome(g.id);}else if(g.mode==='stir'){if(s.mixing>=.995)s.returnHome('spoon');else{s.objects.spoon.held=false;s.objects.spoon.slot='stir';}}else if(g.mode==='unlock'){s.objects.portafilter.held=false;}else if(g.moved){const d=nearest(g.id,g.x,g.y);if(d?.key==='iceScoop'){if(!s.addIceScoop()){s.returnHome('iceScoop');onError(s.bucketRemaining+s.iceScoopLoaded===0?'The bucket is empty.':'The glass is full.');}}else if(d?.key==='iceBucket'){s.loadIceScoop();s.returnHome('iceScoop');}else if(d?.key==='ice'&&s.addIce(g.id)){}else if(d?.key==='serve'&&s.serveDrink()){}else if(d?.key==='tamp'){s.tamp(1);s.returnHome('tamper');}else if(d?.key==='scoop'){s.scoop();s.put('spoon',[STATIONS.sugar[0],.28,STATIONS.sugar[2]]);}else if(d?.key==='sugar'){const added=s.addSugar();if(added)studio.sugarBurst();if(!added&&s.vessels.glass.contents.coffee>0&&s.vessels.glass.contents.milk>0){s.skipSugar();s.put('spoon',studio.mouth('glass'),'stir');onError('No room for more sugar. You can stir now.');}else s.returnHome('spoon');}else if(d?.key==='stir'&&s.vessels.glass.contents.coffee>0&&s.vessels.glass.contents.milk>0){s.skipSugar();s.put('spoon',studio.mouth('glass'),'stir');}else if(['grinder','group','brew'].includes(d?.key)){s.dock(g.id,d.key);if(d.key==='group')s.twist(1);}else{settle(g);}}else restore(g.id,g.saved);}
  if(canvas.hasPointerCapture?.(g.pointer))canvas.releasePointerCapture(g.pointer);onChange();
 }
 function down(e){pointers.add(e.pointerId);studio.director?.interrupt();if(pointers.size>1){finish(true);return;}if(e.button!==undefined&&e.button!==0)return;let id=studio.hit(e.clientX,e.clientY);if(id==='glass'&&s.objects.spoon.slot==='stir')id='spoon';if(!id)return;studio.controls.enabled=false;e.preventDefault();canvas.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing';gesture={id,pointer:e.pointerId,startX:e.clientX,startY:e.clientY,x:e.clientX,y:e.clientY,mode:'control',moved:false};
  if(id==='power'){s.power=!s.power;s.stop();return;}if(id==='sound'){toggleSound();return;}
  if(id==='grindLever'){if(!s.beginGrind())onError(s.grounds>=18?'The basket is full. Tamp the grounds.':'Place the portafilter under the grinder first.');return;}
  if(id==='brewLever'){if(s.brewing)s.brewing=false;else if(!s.beginBrew())onError(recovery(s));return;}
  const o=s.object(id);if(!o){finish();return;}gesture.saved=save(o);gesture.origin=studio.presentation?.(id)??[...o.position];o.position=[...gesture.origin];gesture.startWorld=studio.atPlane(e.clientX,e.clientY,o.position);
  if(o.slot==='pour'&&['cup','milk'].includes(id)){gesture.saved=o.pourHome??gesture.saved;gesture.mode='drag';s.pick(id);studio.setTargets(destinations(id,s,studio));return;}
  if(id==='portafilter'&&s.lock>.1){gesture.mode='unlock';return;}
  if(id==='spoon'&&o.slot==='stir'){gesture.mode='stir';gesture.lastStirX=e.clientX;o.held=true;return;}
  if(!s.pick(id)){finish();return;}gesture.mode='drag';studio.setTargets(destinations(id,s,studio));onChange();
 }
 function move(e){if(!gesture){const id=studio.hit(e.clientX,e.clientY);studio.highlight(id);canvas.style.cursor=id?'grab':'grab';return;}const g=gesture;if(e.pointerId!==g.pointer)return;g.x=e.clientX;g.y=e.clientY;const dx=g.x-g.startX,dy=g.y-g.startY;g.moved ||=Math.hypot(dx,dy)>4;
  if(g.mode==='control')return;
  if(g.mode==='unlock'){s.twist(clamp(g.saved.lock+dx/55,0,1));if(s.lock<.1&&Math.abs(dy)>20){s.pick(g.id);g.mode='drag';g.origin=[...s.objects[g.id].position];g.startWorld=studio.atPlane(g.x,g.y,g.origin);}return;}
  if(g.mode==='tamp'){s.tamp(clamp((g.y-g.pivotY)/24,0,1));const p=s.objects.portafilter.position;s.objects.tamper.position=[p[0],p[1]+.14-s.compression*.12,p[2]];return;}
  if(g.mode==='pour'&&Math.abs(g.x-g.pivotX)>85){s.pouring=null;s.objects[g.id].tilt=0;delete s.objects[g.id].pourHome;g.mode='drag';g.origin=[...s.objects[g.id].position];g.startWorld=studio.atPlane(g.x,g.y,g.origin);g.startX=g.x;g.startY=g.y;studio.setTargets(destinations(g.id,s,studio));return;}
  if(g.mode==='pour'){s.pour(g.id,'glass',.85);return;}
  if(g.mode==='stir'){const bowl=studio.project([STATIONS.sugar[0],.28,STATIONS.sugar[2]]);if(Math.abs(g.y-g.startY)>110||(Math.abs(g.y-g.startY)>30&&Math.hypot(g.x-bowl.x,g.y-bowl.y)<35)){s.stirVelocity=0;const spoon=s.objects.spoon;spoon.position=studio.presentation?.('spoon')??[...spoon.position];spoon.held=false;s.pick('spoon');g.mode='drag';g.origin=[...spoon.position];g.startWorld=studio.atPlane(g.x,g.y,g.origin);g.startX=g.x;g.startY=g.y;studio.setTargets(destinations('spoon',s,studio));return;}const distance=clamp(g.x-g.lastStirX,-200,200);g.lastStirX=g.x;const angle=distance*Math.PI/100,steps=Math.ceil(Math.abs(angle)/.45);for(let i=0;i<steps;i++)s.stir(angle/steps);return;}
  if(!g.moved)return;const p=studio.atPlane(g.x,g.y,g.origin);if(p&&g.startWorld)s.object(g.id).position=p.map((v,i)=>g.origin[i]+v-g.startWorld[i]);
  const d=nearest(g.id,g.x,g.y);
  if(d?.key==='pour'){g.mode='pour';g.pivotY=g.y;g.pivotX=g.x;const m=studio.mouth('glass'),h=g.id==='cup'?.36:.79;s.objects[g.id].position=[m[0]+Math.sin(1.1)*h,m[1]+.18-Math.cos(1.1)*h,m[2]];s.objects[g.id].tilt=1.1;s.pour(g.id,'glass',.85);}
 }
 function up(e){pointers.delete(e.pointerId);if(gesture?.pointer===e.pointerId)finish(false);}
 function cancel(e){pointers.delete(e.pointerId);if(gesture?.pointer===e.pointerId)finish(true);}
 canvas.addEventListener('pointerdown',down,true);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',up,true);canvas.addEventListener('pointercancel',cancel,true);canvas.addEventListener('lostpointercapture',e=>{if(gesture?.pointer===e.pointerId)finish(true);});canvas.addEventListener('wheel',()=>studio.director?.interrupt(),{passive:true});
 const cancelAll=()=>{finish(true);pointers.clear();};window.addEventListener('blur',cancelAll);window.addEventListener('resize',cancelAll);window.addEventListener('keydown',e=>{if(e.key==='Escape')cancelAll();});
 return{cancel:cancelAll,update(){},get active(){return gesture;}};
}
